			<h1 style='padding: 12px 0px 34px 0;' id="djmz">销退单</h1>
			<!-- <div style='float:right;    font-size: 14px;font-weight: 800;'>页码:{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</div> -->
			</div> 
                 
				<table  border='0' style='width:100%;' id='printtable1'>
        <tr >
					       <img ref="barcode" id="barcode"/>
					        <!-- <td style='text-align:center;'>单位名称：<span id=''>{{dwmc}}</span></td> -->
					    </tr>					
					      	<tr height='30px;'>
					        <td style='text-align:left;'>出库单号：<span id=''>{{item.单据编号}}</span></td>
					        <td style='text-align:center;'>单位名称：<span id=''>{{dwmc}}</span></td> 
					    </tr>                        
					    </table> 
				<table  border='1'  style='width:100%; display:inline-table;border-collapse: collapse;' id='printtable2'>
					    <tr height='40px;'>
							<td style='text-align:center;width:5%'>序号</td>
					        <td style='text-align:center;width:30%'>商品名称</td>


					        <td style='text-align:center;width:10%'>规格</td> 
					        <td style='text-align:center;width:10%'>型号</td> 
                  <td style='text-align:center;width:10%'>数量</td> 
                  <td style='text-align:center;width:10%'>单位</td> 
					        <td style='text-align:center;width:10%'>单价</td> 
                  <td style='text-align:center;width:10%'>金额</td> 
                 
					    </tr>
					    <tr height='40px;' v-for="(ite,ind) in tableData.slice(index,index+3)" :key="ind">
							<td style='text-align:center;'>{{ind}}</td>
					        <td style='text-align:center;'>{{ite.产品名称}}</td>
					        <td style='text-align:center;'>{{ite.规格}}</td>
					        <td style='text-align:center;'>{{ite.型号}}</td>
					        <td style='text-align:center;'>{{ite.数量}}</td>
                  <td style='text-align:center;'>{{ite.单位}}</td>
                  <td style='text-align:center;'>{{ite.单价}}</td>
                  <td style='text-align:center;'>{{ite.金额}}</td>
					    </tr>	
              <tr height='40px;'>
							<td style='text-align:center;'>合计</td></td>
					        <td style='text-align:center;'></td>
					        <td style='text-align:center;'></td>
					        <td style='text-align:center;'></td>
					        <td style='text-align:center;'></td>
                  <td style='text-align:center;'></td>
                  <td style='text-align:center;'></td>
                  <td style='text-align:center;' v-if="jesz[index+2]">{{jesz[index+2]}}</td>
                  <td style='text-align:center;' v-else-if="!jesz[index+2] && jesz[index+1]">{{jesz[index+1]}}</td>
                  <td style='text-align:center;' v-else-if="!jesz[index+2] && !jesz[index+1]">{{jesz[index]}}</td>
					    </tr>
		         </table>
				 <table  border='0' style='width:100%;' id='printtable4' >		 							   
		  		   <tr height='30px;'>
					     <td style='text-align:left;'>页码:<span id=''>{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</span></td>
					     <td style='text-align:center;'><span >总金额:￥{{formData.zje}}元</span></td>
					    <!--  <td style='text-align:right;'><span></span></td> -->
		             <td style='text-align:right;'><span>总金额合计(大写):{{'负'+jedx}}</span></td>   
			      </tr>	
		 		</table>  
				<table  border='0' style='width:100%;' id='printtable3'>
			          <tr height='30px;'>
					     <td style='text-align:left;'>制单：<span id=''>{{yhmz}}</span></td>
					     <td style='text-align:center;'>保管员：<span id=''>{{item.用户名}}</span></td>
					     <td style='text-align:right;'>入库日期：<span id=''>{{formData.date}}</span></td> 
			      </tr>			      
			   </table> 
			   
          
				<div style='page-break-after:always;'></div>
			</div>
			</div> 
			</div>
			</el-dialog>
		</div>
	</d2-container>
  
</template>

<script>
import jsbarcode from 'jsbarcode'
import setter from '@/libs/setter.js'
import {
		Query,
		Aud
	} from '@api/shuju.js'
export default {
	name: 'XsEdit',  
  components: {
			
		},
          data () {
            return {
             fullscreenLoading: false,
             loading: false,
              formData: {
                name: '',
                date:'',
                ddbh:'增加明细生成编号',
                fkfs:'',
                khmc:'',
                zje:'',
                djlx:''
              },
             formRules:{
               khmc:[{
                   required: true, message: '请输入客户名称' 
               }]
              },  
              findList:[],
              fkfsList:[
                { value:'支付宝', label:'支付宝' },
                { value:'微信', label:'微信' },
                { value:'转账', label:'转账' },
                { value:'现金', label:'现金' }, 
              ],
              dialogTableVisible: false,
              dialogTableVisible2: false,
              isShow:true,
              dwmc:'',
              yhmz:'',
              jedx:'',
              fyjq:[],
              nameList:[],
              khList:[],
              cpList:[],
              yhList:[],
              tableData: [],
              tableData2:[],
              nowView:2,
              heji:[],
              jesz:[],
              authKeys:[],
              tablePage: { // 分页属性---
					currentPage: 1, //当前页 相当于layui的page
					pageSize: 10,  	//每页条数 相当于layui的limt
					totalResult: 0  //总页数   相当于count				
				},
              //搜索变量
				 searchFilter: {
				    	name: '',
					    //account: '',
				     	disable: ''
			      	},
          
               
        }
            },
    props: {
			    passID: Number,	
          authKeys: String,		
		      },
  	mounted() {
      this.getcpData()
			this.checkDev()
			//this.InitRoles()
			this.InitCginfo()
      this.getkhData()
      this.getyhData()
      
			

		},
     methods: {
			back() {
				this.$emit('goBack')
			},
			checkDev() {
				this.isDev = (process.env.NODE_ENV === 'development') ? true : false
        
			},  
      exportDataEvent () {
              this.$refs.xTable.openExport()
            },  
      sumNum (list, field) {
              let count = 0
               let zje = 0
              list.forEach(item => {
                count += Number(item[field])
                zje += Number(item['金额'])
              })
              this.formData.zje = zje
              console.log( this.formData.zje)
              return count
            },
      
            footerMethod ({ columns, data }) {
              
              const footerData = [
                columns.map((column, columnIndex) => {
                  if (columnIndex === 0) {
                    return '合计'
                  }
                  if (['数量', '金额'].includes(column.property)) {
                    let zje = 0
                   let ndata = data.map(function(v,i){
                     let sl3 = v.数量 > 0 ? 0-v.数量 : v.数量 
                     let je = sl3*v.单价
                        return Object.assign(v,{金额:je});
                   })
                 
                
                    return this.sumNum(ndata, column.property)
                  }
                
                  return null
                })
              ]
              this.heji = footerData
              return footerData
             
            },
            add(){
              const $grid = this.$refs.xTable
              $grid.insertAt({}, -1)
                
              let xsz = setter.getTime().split(' ');
              let xx = xsz[1].split(':');//用split()函数将字符串分割成数组，（）里面的参数是分割条件;
              let xs = xsz[0].split('-');//用split()函数将字符串分割成数组，（）里面的参数是分割条件;
              let bh =  xs[0]+xs[1]+xs[2]+xx[0]+xx[1]+xx[2];
              this.formData.ddbh = 'XSTH' + bh;
              this.formData.djlx = '销后退回'; 
              
            },
            del(){
              this.deleteInfo()
              /* const $grid = this.$refs.xTable
              $grid.removeCheckboxRow() */
              
            },
            addduo(){
              const $grid2 = this.$refs.xTable1
              const $grid = this.$refs.xTable
              let sj = $grid2.getCheckboxRecords().map(function(v,i){
                delete v.id 
                delete v.日期 
                return v
              })
              console.log(sj)
              $grid.insertAt(sj, -1)
                
              let xsz = setter.getTime().split(' ');
              let xx = xsz[1].split(':');//用split()函数将字符串分割成数组，（）里面的参数是分割条件;
              let xs = xsz[0].split('-');//用split()函数将字符串分割成数组，（）里面的参数是分割条件;
              let bh =  xs[0]+xs[1]+xs[2]+xx[0]+xx[1]+xx[2];
              if (this.passID === '') {
                console.log(this.passID)
              this.formData.ddbh = 'XSTH' + bh;
              this.formData.djlx = '销后退回'; 
               this.formData.date = xsz[0]
              }
               this.dialogTableVisible = false
            },
            clearFilter() {
				let obj = this.searchFilter
				for (let key in obj) {
					this.searchFilter
					obj[key] = null
				}
			},
            cellClickEvent ({ column,row }) {
              /* console.log(`单元格点击${column.title}`)
              console.log(column.title)
              console.log(row) */
            },
            gxsj({ row, rowIndex, $rowIndex, column, columnIndex, $columnIndex }){
              console.log(column.title)
              console.log(row)
              let bgsj =  this.$refs.xTable.getTableData()
              console.log(bgsj)
              if(row.id){
              //let sl2 = row.数量 < 0 ? 0-row.数量 : row.数量
              let up = [{'id':row.id}]
              let jeobj
              let upobj = {[column.title]:row[column.title]}
              if(upobj){
                 Object.assign(up[0],upobj);
              }
               if (['数量'].includes(column.title)) {
                 let _this = this
                 let sl3 = row.数量 > 0 ? 0-row.数量 : row.数量 
                 jeobj = {金额:row.单价 * sl3} 
                 //let sl2 = val.数量 < 0 ? 0-val.数量 : val.数量                                 
                  Object.assign(up[0],jeobj,{数量:sl3});
                  console.log(row)
               
              }  
               if (['单价'].includes(column.title)) {
                 jeobj = {金额:row.单价*row.数量}                                 
                  Object.assign(up[0],jeobj);
              } 
              delete up.启用;         
              console.log(up)
                Aud({
							    reqType:'update',
					        content: up,
					            tablename:'出单'
								})
								.then(res => {
									//this.fullscreenLoading = false
									this.$message.success('修改成功')
								//	this.$emit('goBack')
								})
								.catch(err => {
									//this.fullscreenLoading = false
								})  
            }else{
               
            }
            },
             getkhData() {
               
               Query({
							tj:`启用 = -1 `,
							tablename:'客户',
							field:'id'
						})
						.then(res => {
							this.khList  = res.data
							/* let khsj = res.data.map(function(v,i){
                 return  { value: v.客户ID, label:v.客户名称 } 
              })
							this.khList = khsj		*/					 							
						}) 
						.catch(err => {
							// 异常情况
							
						})
			 }, 
       getyhData() {
               Query({
							tj:`用户名 is not null `,
							tablename:'用户',
							field:'id'
						})
						.then(res => {
							//this.tableData = res.data()
							let yhsj = res.data.map(function(v,i){
                 return  { value: v.用户名, label:v.用户名 } 
              })
							this.yhList = yhsj							 							
						})
						.catch(err => {
							// 异常情况
							
						})
			 }, 
            getcpData() {
               Query({
							tj:true,
							tablename:'产品',
							field:'id'
						})
						.then(res => {
							//this.tableData = res.data()
							//console.log(res.data)
							this.cpList = res.data							 							
						})
						.catch(err => {
							// 异常情况
							
						})
			 }, 
       getTableData() {
					let tjx	
					this.loading = true
				 if(this.searchFilter.name !='' && this.searchFilter.name != null ){
					tjx =`产品名称 like '%${this.searchFilter.name}%'`	
					//tj += ' and ' + tjx
					}else{
						tjx = true
						//tj += ' and ' + tjx 
					}	
					Query({

							limit: this.tablePage.pageSize,
							page: this.tablePage.currentPage,
							tj:tjx,
							tablename:'产品',
							field:'id',
						})
						.then(res => {							
						//this.cpList = res.data
						this.tableData2 = res.data
						this.tablePage.totalResult = res.count
						this.loading = false
							
							
						})
						.catch(err => {
							// 异常情况
							this.loading = false
						})
				
			   
			}, 
      			save() {
              console.log(this.formData)
				//this.$refs.form.validate((valid) => {
  
					if (this.formData.khmc != '' && this.formData.ddbh != '增加明细生成编号') {
           let _this = this
             
              let bgsj =  this.$refs.xTable.getTableData()
              console.log(bgsj.tableData)
              let sjs = bgsj.tableData.map(function(v,i){
